            if (errors.length > 0) {
              const last = errors[0];
              errorsMsg += `\nÚltimo erro: _${last.message}_ em \`${last.path}\` (${last.timestamp})`;
            }
          } else {
            errorsMsg = '\n\n✅ *Nenhum erro de página registrado nas últimas 24h.*';
          }
        } catch (_) {
