        stepMsg = `🟢 *Diagnóstico do Sistema Conecta King:*\n\n` +
          `• *Status Geral:* ${ok ? '100% Operacional ✅' : 'Atenção ⚠️'}\n` +
          `• *Servidor / HTTP:* ${h.statusCode}\n` +
          `• *Backend Laravel:* ${ok ? 'Ativo' : 'Com problemas'}\n` +
